window.docContents[2].resolve({"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Canonical-Forms":{"contents":"As we saw for the very simple language in the Types\nchapter, the first step in establishing basic properties of\nreduction and types is to identify the possible canonical\nforms (i.e., well-typed values) belonging to each type.  For\nBool, these are again the boolean values true and false; for\narrow types, they are lambda-abstractions.\n\nFormally, we will need these lemmas only for terms that are not\nonly well typed but closed — i.e., well typed in the empty\ncontext.\n\ntheorem canonical_forms_bool (t : Tm) (hT : <{ ∅ ⊢ ~t ⦂ Bool }>) (hv : t.IsValue) :\n    t = <{ true }> ∨ t = <{ false }> := by\n  cases hv with\n  | abs x T t₁ => cases hT\n  | tru => left; rfl\n  | fls => right; rfl\n\ntheorem canonical_forms_fun (t : Tm) (T₁ T₂ : Ty)\n    (hT : <{ ∅ ⊢ ~t ⦂ ~T₁ → ~T₂ }>) (hv : t.IsValue) :\n    ∃ x u, t = <{ λ ~x : ~T₁ . ~u }> := by\n  cases hv with\n  | abs x T t₁ => cases hT with | abs _ _ _ _ _ _ =>\n    exists x, t₁\n  | tru => cases hT\n  | fls => cases hT\n\n\n","context":"Type Systems\u0009StlcProp: Properties of STLC","header":"6.1. Canonical Forms","id":"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Canonical-Forms"}});